const text = $input.first().json.chatInput

try {
    const lines = text
        .split(/\r?\n/)
        .filter(line => line.trim() !== '');

    // Must have at least header + 1 row
    if (lines.length < 2) {
        return [{ json: { isCsv: false, text } }];
    }

    // Detect delimiter
    const delimiters = [',', ';', '\t'];

    let delimiter = null;
    let columnCount = 0;

    for (const d of delimiters) {
        const cols = lines[0].split(d).length;

        if (cols >= 2) {
            delimiter = d;
            columnCount = cols;
            break;
        }
    }

    if (!delimiter) {
        return [{ json: { isCsv: false, text } }];
    }

    // Every row must have same number of columns
    const validStructure = lines.every(line =>
        line.split(delimiter).length === columnCount
    );

    if (!validStructure) {
        return [{ json: { isCsv: false, text } }];
    }

    const fs = require('fs');

    fs.writeFileSync('/output/data.csv', text);

    return [{
        json: {
            isCsv: true,
            text
        }
    }];

} catch (error) {
    return [{
        json: {
            isCsv: false,
            text,
            error: error.message
        }
    }];
}

