let csv = fs.readFileSync('/output/data.csv', 'utf8');

let rows = csv
  .trim()
  .split('\n')
  .map(row => row.split(','));

// Safety check
for (const column of columns) {
  if (column.length !== rows.length) {
    throw new Error(
      `Column "${column[0]}" has ${column.length - 1} values but CSV has ${rows.length - 1} data rows`
    );
  }
}

// Add all new headers
for (const column of columns) {
  rows[0].push(column[0]);
}

// Add all values
for (let rowIndex = 1; rowIndex < rows.length; rowIndex++) {
  for (const column of columns) {
    rows[rowIndex].push(column[rowIndex]);
  }
}

const updatedCsv = rows
  .map(row => row.join(','))
  .join('\n');

fs.writeFileSync('/output/data.csv', updatedCsv);

return [
